bounded_host_request.command:
set -euo pipefail
pg="$(docker ps --format '{{.Names}}' | grep -Ei '(^|[-_])postgres([-_]|$)' || true)"
test "$(printf '%s\n' "$pg" | sed '/^$/d' | wc -l)" -eq 1 || exit 61
user="$(docker exec "$pg" sh -c 'printf %s "$POSTGRES_USER"')"
net="$(docker inspect -f '{{range $k,$v := .NetworkSettings.Networks}}{{println $k}}{{end}}' "$pg" | sed '/^$/d')"
test -n "$user" && test "$net" = deploy_default || exit 62
secret="$HOME/.local/state/create-videobot/secrets/gserver_postgres_password"
test -f "$secret" && test ! -L "$secret" && test "$(stat -c %a "$secret")" = 600 || exit 63
docker image inspect create-videobot:local-poll >/dev/null 2>&1 || exit 64
docker run --rm --network "$net" --pull never --read-only --cap-drop ALL --security-opt no-new-privileges:true \
 --mount "type=bind,source=$secret,target=/run/secrets/videobot_db_password,readonly" \
 -e "GSERVER_DB_USER=$user" --entrypoint node create-videobot:local-poll --input-type=module -e '
import pg from "pg";
import {readFileSync} from "node:fs";
import {applyCreatorSchema} from "./src/runtime/creatorMigrate.mjs";
const pass=readFileSync("/run/secrets/videobot_db_password","utf8").trim();
const pool=new pg.Pool({host:"deploy-postgres-1",port:5432,user:process.env.GSERVER_DB_USER,password:pass,database:"videobot",max:1,connectionTimeoutMillis:5000});
try {
 await pool.query("SELECT 1");
 const a=await applyCreatorSchema({pool});
 if(a.migrations!==12)throw Object.assign(Error("MIGRATION_INCOMPLETE"),{code:"MIGRATE_COUNT"});
 const q=await pool.query("SELECT to_regclass($1) IS NOT NULL AS cursor, to_regclass($2) IS NOT NULL AS packs, to_regclass($3) IS NOT NULL AS sessions",["videobot_poll_cursor","videobot_sticker_packs","videobot_creator_sessions"]);
 if(q.rows.length!==1||!q.rows[0].cursor||!q.rows[0].packs)throw Object.assign(Error("MIGRATION_READBACK_MISSING"),{code:"MIGRATE_READBACK"});
 process.stdout.write("STK04_DATABASE_MIGRATIONS=12\n");
 process.stdout.write("STK04_DATABASE_READBACK=PASS\n");
}catch(err) {
 const code=String(err?.code??"");
 const exit=code==="28P01"?80:code==="42501"?81:code==="3D000"?82:code==="ECONNREFUSED"?83:code==="ENOTFOUND"?84:code==="MIGRATE_READBACK"?85:code==="MIGRATE_COUNT"?86:87;
 process.exitCode=exit;
}finally{await pool.end()}
'
